/**
 * Riverside Regional Hospital: signed clinical documents.
 *
 * One item per signed document: an emergency department provider note, an admission history and
 * physical (H&P), a daily progress note, a specialty consult, or a discharge summary. Several documents
 * usually belong to one hospital encounter; the `encounter` entry in each item says which.
 *
 * The narrative is the note text the clinician signed. The payload holds the structured parts of the
 * note as the hospital EHR stored them when the note was signed: the encounter context, diagnoses, the
 * home medication list, inpatient medications, allergies, vital signs, and copies of lab results the
 * author reviewed.
 *
 * Read these before mapping:
 *
 * - **Every document re-lists the home medications and allergies.** Each list is a snapshot taken when
 *   that document was signed, with that document's status for each drug. Five documents in one stay
 *   mean five copies of the same drugs. For the hospital's final word on outpatient medications, use the
 *   most recent `discharge_summary` of the encounter.
 * - **Lab results are copies.** Riverside does not publish lab results as items of their own. A result
 *   appears inside whichever documents reviewed it, so the same result can appear in several items. The
 *   `accession` plus test code identifies one result across documents.
 * - **Lab values are text**, exactly as the lab displayed them: `"182"`, `"7.21"`, `"<0.01"`.
 * - **Payload times are UTC** (`Z`). Riverside is in America/Chicago (UTC-6 standard, UTC-5 daylight
 *   time). The clinical date of an evening visit is the local date, which can be a day earlier than the
 *   UTC date. Times written in the narrative are local wall-clock times.
 * - **No allergy/intolerance distinction.** Everything on the hospital's allergy list is an `allergy`
 *   entry, including side effects such as cough.
 *
 * Envelope conventions: `effective` is the time the document is about (ED arrival for an ED note, time
 * of examination for an H&P, progress note or consult, inpatient admission time for a discharge
 * summary, with `effective_end` = discharge time). `author` is the signing clinician. A signed addendum
 * or correction is a new item that `supersedes` the original and restates the whole document.
 */

/** One entry in a Riverside document payload. Discriminated by `type`. */
export type RiversideEntry =
  | Encounter
  | Diagnosis
  | History
  | Allergy
  | HomeMed
  | InpatientMed
  | Vitals
  | Result
  | Panel
  | FollowUp;

/**
 * The encounter and document context. Exactly one per item, conventionally under the key `enc`.
 */
export interface Encounter {
  type: 'encounter';

  /**
   * Riverside encounter number. One number covers the whole hospital stay, from ED arrival to
   * discharge: the ED note, H&P, progress notes, consults and discharge summary of one stay share it.
   */
  encounter_id: string;

  /**
   * Which kind of document this item is.
   * - 'ed_note': emergency department provider note.
   * - 'hp': admission history and physical, written by the admitting physician.
   * - 'progress_note': daily inpatient note.
   * - 'consult': note from a specialty service asked to see the patient.
   * - 'discharge_summary': written at discharge; covers the whole stay. Its home medication list is
   *   the discharge instructions.
   */
  document_kind: 'ed_note' | 'hp' | 'progress_note' | 'consult' | 'discharge_summary';

  /**
   * Encounter class at the time the document was signed.
   * - 'emergency': the patient was in the ED and not yet admitted.
   * - 'inpatient': admitted (including step-down and ICU).
   * A stay that starts in the ED changes class from 'emergency' to 'inpatient' at admission; earlier
   * documents keep the class they were signed with.
   */
  class: 'emergency' | 'inpatient';

  /** Clinical service of the author, free text as configured at Riverside, e.g. "Emergency Medicine", "Hospital Medicine", "Endocrinology". */
  service: string;

  /** ED arrival time, UTC. Present on every document of a stay that began in the ED. */
  arrived?: string;

  /** Inpatient admission order time, UTC. Absent while the patient is still in the ED. */
  admitted?: string;

  /** Discharge time, UTC. Present only on discharge summaries. */
  discharged?: string;

  /**
   * Where the patient went at the end of this phase of care.
   * - 'admitted': ED patient admitted to Riverside (ED notes only).
   * - 'home': discharged home without services.
   * - 'home_with_services': discharged home with home health.
   * - 'transferred': sent to another hospital.
   * - 'left_against_advice': left before the care team discharged them.
   * Absent on H&Ps, progress notes and consults.
   */
  disposition?: 'admitted' | 'home' | 'home_with_services' | 'transferred' | 'left_against_advice';
}

/**
 * A diagnosis on this document's diagnosis list, as the author left it at signing. Diagnoses are
 * re-entered in each document, so the same condition can appear in several items of one stay with
 * different statuses as the workup progresses.
 */
export interface Diagnosis {
  type: 'diagnosis';

  /** Diagnosis as the clinician wrote it, e.g. "R/O pancreatitis", "Euglycemic DKA, SGLT2 inhibitor-associated". */
  label: string;

  /**
   * ICD-10-CM code chosen by the author or added by coding. Absent on working diagnoses entered as free
   * text. An adverse drug effect is coded as its own diagnosis (an ICD-10-CM T-code), not as an
   * allergy.
   */
  icd10cm?: string;

  /**
   * Riverside local diagnosis code, used where ICD-10-CM is too coarse (for example to separate
   * SGLT2 inhibitor-associated euglycemic DKA from other DKA, which share ICD-10-CM E11.10). Code
   * space: Riverside problem dictionary, `RRH-DX-` followed by digits; stable across years.
   */
  riverside_dx?: { code: string; name: string };

  /**
   * Where the diagnosis stood when the document was signed.
   * - 'working': suspected and under evaluation, not established. A later document may confirm it,
   *   rule it out, or silently drop it; an absent later mention does not mean it was confirmed.
   * - 'ruled_out': considered and excluded. The patient does NOT have this condition.
   * - 'active': established and present.
   * - 'resolved': established during this stay and no longer present at signing (e.g. a ketoacidosis
   *   that cleared). The patient had it.
   */
  status: 'working' | 'ruled_out' | 'active' | 'resolved';

  /**
   * - 'principal': the main reason for the hospital stay. Set on H&Ps and discharge summaries only.
   * - 'secondary': any other diagnosis addressed in this document.
   * Absent on ED notes, which do not rank diagnoses.
   */
  rank?: 'principal' | 'secondary';
}

/**
 * A line of past medical history as recorded in this document. Taken from the patient, outside
 * records, or earlier Riverside documents, and not re-verified: stages and dates can be out of date.
 */
export interface History {
  type: 'history';

  /** Condition as written, e.g. "CKD stage 3a", "Type 2 diabetes". */
  condition: string;

  /** ICD-10-CM code if the author picked one from the problem dictionary; often absent. */
  icd10cm?: string;

  /** Onset as written, free text and not normalized: "2016", "~10 years", "childhood". Absent if not stated. */
  onset_text?: string;

  /**
   * Where the line came from.
   * - 'patient': patient or family report.
   * - 'outside_records': another organization's records (e.g. a primary care summary).
   * - 'riverside': an earlier Riverside document.
   */
  source: 'patient' | 'outside_records' | 'riverside';
}

/**
 * An entry on Riverside's allergy list as shown in this document. Riverside keeps one list called
 * "Allergies" and does not separate allergies from intolerances or side effects: a drug that once
 * caused a cough is listed the same way as one that caused anaphylaxis. Read `reaction` to tell them
 * apart. Re-listed in every document.
 */
export interface Allergy {
  type: 'allergy';

  /**
   * Substance as entered, e.g. "lisinopril", "penicillins". If the patient has no known allergies, the
   * list has exactly one entry with substance "NKDA" and no other fields.
   */
  substance: string;

  /** RxNorm ingredient CUI when the substance is a single drug ingredient; absent for classes, foods and "NKDA". */
  rxnorm_ingredient?: string;

  /** Reaction as entered, free text, e.g. "cough", "hives". Absent if unknown. */
  reaction?: string;

  /**
   * Severity as entered.
   * - 'mild': bothersome, not dangerous.
   * - 'moderate': needed treatment or stopping the drug urgently.
   * - 'severe': life-threatening (e.g. anaphylaxis, angioedema).
   * - 'unknown': not recorded.
   */
  severity: 'mild' | 'moderate' | 'severe' | 'unknown';
}

/**
 * One line of the home (outpatient) medication list, with this document's decision about it.
 *
 * The meaning of `status` depends on `document_kind` in the item's `encounter` entry:
 * in ED notes, H&Ps, progress notes and consults it is the plan **during the stay**; in a discharge
 * summary it is the instruction **after discharge**. Only the latest discharge summary of an encounter
 * says what the patient should take at home.
 *
 * Entry keys are chosen per document. They often repeat across the documents of a stay (`med_empa`),
 * but nothing guarantees it: match lines across documents by `rxnorm_ingredient` and `dose_text`, never
 * by key.
 */
export interface HomeMed {
  type: 'home_med';

  /** Drug and form as written on the list, e.g. "empagliflozin 10 mg tablet". */
  drug_name: string;

  /**
   * RxNorm ingredient CUI (not a clinical drug code: strength and form are in `drug_name` and
   * `dose_text`). Absent for combination products and supplements that are not mapped.
   */
  rxnorm_ingredient?: string;

  /** Dose per administration as written, e.g. "1000 mg", "10 units". Text, not normalized. */
  dose_text: string;

  /** Directions as written, e.g. "1 tab PO BID with meals". Not normalized. */
  sig: string;

  /**
   * This document's decision for the drug (see the interface comment for during-stay vs after-discharge).
   * - 'not_reconciled': listed from the patient or prior records; the author made no decision. Typical
   *   of ED notes. Does not mean the patient is taking it now.
   * - 'continue': keep taking (or keep giving in hospital). In a discharge summary this includes a drug
   *   that was held during the stay and is restarted at discharge.
   * - 'held': do not take for now. Not stopped: someone decides later whether to restart, and
   *   `restart_advice` says which way this author leans. `instructions` usually says who decides and
   *   when.
   * - 'stopped': discontinued by this author.
   * - 'new': started during this stay, to continue.
   * - 'changed': same drug, new dose or directions; `dose_text`/`sig` show the new ones.
   */
  status: 'not_reconciled' | 'continue' | 'held' | 'stopped' | 'new' | 'changed';

  /**
   * On 'held' lines only: what this author advises about restarting. Absent on other statuses, and on
   * held lines where the author gave no advice.
   * - 'resume_when_able': restart once the reason for holding has passed (eating again, creatinine back
   *   to baseline). `instructions` usually names the condition.
   * - 'prescriber_decides': no advice either way; the outpatient prescriber decides.
   * - 'advise_against': the author recommends not restarting. The line is held rather than stopped
   *   because the outpatient prescriber makes the final decision. The patient is not taking the drug.
   */
  restart_advice?: 'resume_when_able' | 'prescriber_decides' | 'advise_against';

  /** Free-text instruction attached to the status, e.g. "Do not resume until reviewed by PCP". Absent if none. */
  instructions?: string;
}

/**
 * A medication ordered for use in the hospital only (infusions, IV fluids, inpatient-only drugs).
 * Not part of the home list and not continued after discharge unless it also appears there as 'new'.
 */
export interface InpatientMed {
  type: 'inpatient_med';

  /** Drug or fluid as ordered, e.g. "insulin regular (human) IV infusion", "lactated Ringer's". */
  drug_name: string;

  /** RxNorm ingredient CUI; absent for IV fluids and mixtures. */
  rxnorm_ingredient?: string;

  /** Route as ordered, e.g. "IV", "SubQ", "PO". */
  route: string;

  /** Dose or rate as ordered, free text, e.g. "per DKA protocol, 0.1 units/kg/h", "150 mL/h". */
  dose_text: string;

  /** First administration, UTC. */
  started: string;

  /** Last administration or order discontinue time, UTC. Absent if still running when the document was signed. */
  stopped?: string;
}

/** One set of vital signs taken at one time. Any member may be absent if not measured. */
export interface Vitals {
  type: 'vitals';

  /** When the vitals were taken, UTC. */
  taken: string;

  /** Blood pressure in mmHg. */
  bp?: { systolic_mmhg: number; diastolic_mmhg: number };

  /** Heart rate, beats per minute. */
  heart_rate_bpm?: number;

  /** Respiratory rate, breaths per minute. */
  resp_rate_per_min?: number;

  /** Temperature in degrees Fahrenheit, as entered by nursing. */
  temp_f?: number;

  /** Oxygen saturation by pulse oximetry, percent (0–100). */
  spo2_pct?: number;

  /** Weight in kilograms (converted by the EHR from whatever unit was entered). */
  weight_kg?: number;
}

/**
 * The value part of a lab result. Used on its own as `Result` and for each component of a `Panel`.
 */
export interface ResultValue {
  /**
   * Riverside lab test. `local_code` is the Riverside lab dictionary code (stable across years).
   * `loinc` is present for most chemistry and hematology tests and absent for some point-of-care and
   * send-out tests (e.g. beta-hydroxybutyrate). `name` is the display name.
   */
  test: { local_code: string; loinc?: string; name: string };

  /**
   * Result exactly as displayed by the lab, as text. Usually a decimal number (`"182"`, `"7.21"`), but
   * may carry a comparator (`"<0.01"`, `">600"`) or be words (`"Hemolyzed, see comment"`). Parse with
   * care; a comparator means the true value is beyond the reportable limit.
   */
  value: string;

  /**
   * Unit as the lab reports it, close to UCUM: "mg/dL", "mmol/L", "U/L", "ng/mL", "10*3/uL" (thousands
   * per microliter), "g/dL", "mmHg", "mL/min/1.73m2". Absent for unitless results (pH).
   */
  unit?: string;

  /** Reference range as displayed, text, in the same unit as `value`, e.g. "70-99", "<0.04". Absent if the lab gives none. */
  ref_range?: string;

  /**
   * Abnormal flag from the lab.
   * - 'H' / 'L': above / below the reference range.
   * - 'HH' / 'LL': critically high / low.
   * - 'A': abnormal, no direction (non-numeric results).
   * Absent when the value is within range.
   */
  flag?: 'H' | 'L' | 'HH' | 'LL' | 'A';
}

/**
 * Copy of one lab result reviewed in this document. The same result (same `accession` and
 * `test.local_code`) can appear in several documents; it is one result, not several.
 */
export interface Result extends ResultValue {
  type: 'result';

  /** Riverside lab accession number for the specimen. With `test.local_code` it identifies the result. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /**
   * Status of the result when this document copied it.
   * - 'preliminary': reported but not verified; may change.
   * - 'final': verified.
   * - 'corrected': a final value that the lab later changed; `value` is the corrected value.
   * A document never updates after signing, so a later document can show a different status or value
   * for the same result. Use the copy with the most advanced status.
   */
  status: 'preliminary' | 'final' | 'corrected';
}

/**
 * Copy of a panel of results from one specimen (basic metabolic panel, CBC, blood gas). Components carry
 * their own codes, values and flags; the panel carries what they share. Same duplication rules as
 * `Result`.
 */
export interface Panel {
  type: 'panel';

  /** Riverside panel order code and name, e.g. { local_code: "BMP", name: "Basic metabolic panel" }. LOINC present when the panel has one. */
  panel: { local_code: string; loinc?: string; name: string };

  /** Riverside lab accession number for the specimen. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /** Status of the panel as a whole when copied; same values and meaning as `Result.status`. */
  status: 'preliminary' | 'final' | 'corrected';

  /**
   * Component results, in the lab's display order. Includes computed values the lab reports with the
   * panel (anion gap, eGFR). eGFR at Riverside is CKD-EPI 2021 (race-free) for all results since 2023.
   */
  components: ResultValue[];
}

/** A follow-up the author arranged or recommended. Mostly in discharge summaries. */
export interface FollowUp {
  type: 'follow_up';

  /** Clinician, clinic or service to follow up with, as written, e.g. "Primary care (Northgate Family Medicine)". */
  with: string;

  /** When, as written, e.g. "within 1 week", "2024-11-12". Not normalized. */
  when_text: string;

  /** What the follow-up is for, free text. */
  purpose: string;
}
/**
 * Consumer views, version 2: the small shapes a patient-facing chart app reads.
 *
 * These are defined by the consumer, not by any source. A mapper turns one source's FOLIO record items
 * for one patient into these rows. The consumer merges rows from several sources itself, so a mapper
 * reports only what its own source says, and never invents, infers from other sources, or "corrects"
 * what the source records.
 *
 * Contract (see `Transform`): the mapper receives every item one source published for one patient,
 * in no particular order and including items that were later superseded or retracted, plus an
 * `asOf` date. It returns the rows that describe that source's record as it stood at the end of that
 * date.
 *
 * Conventions for every view:
 *
 * - **Scope in time.** An item is in scope when its envelope `recorded` time is on or before the end of
 *   the `asOf` day in America/Chicago. Ignore items recorded later. Apply the FOLIO correction rules to
 *   the items in scope: an item listed in another in-scope item's `supersedes` or `retracts` (same
 *   issuer) is not current; supersession is transitive. Use only current items, except where a view
 *   below says otherwise.
 * - **Time zone.** The consumer displays everything in America/Chicago, the patients' home zone. "Local
 *   date" and "local time" below mean wall-clock date/time in America/Chicago (UTC-6 standard, UTC-5
 *   daylight time). A date-time with no offset and no zone (for example a phone's wall clock) is taken to
 *   be America/Chicago local time: report it as written, do not shift it, and do not leave it out.
 * - **Partial dates.** `PartialDate` strings keep the precision the source actually knows: "2016"
 *   means some time in 2016, never 2016-01-01. Never pad a year-only or month-only date.
 * - **Only what the source records.** Rows come from structured payload entries. Narrative text may be
 *   used to understand an entry but must not be the only basis for a row.
 * - **Evidence.** Every row lists the items (and payload entry ids) it was built from, so the consumer
 *   can show the source text behind a fact. Cite at least the item whose entry gives the row's current
 *   state.
 * - **Sensitive entries are reported, never dropped.** Report every entry the source holds, including
 *   ones it marks restricted, confidential or sensitive. Mark such rows with `sensitivity` (see
 *   `Sensitivity`). Whether a sensitive fact is shown or shared is decided later, by the patient, at
 *   disclosure time; it is never decided by a mapper.
 * - **Determinism.** Same input, same output: no clock, randomness, network or file access.
 */

/** A FOLIO record item in its JSON form (see the FOLIO record-item spec). */
export interface FolioItem {
  folio: string;
  /** Item id (ULID), unique within the issuer. */
  id: string;
  /** did:web of the issuing organization. */
  issuer: string;
  /** Patient id at this issuer. */
  patient: string;
  /** When the clinical event happened: RFC 3339 date-time with offset, or a full or partial date. */
  effective: string;
  effective_end?: string;
  /** When the issuer committed this item: RFC 3339 date-time with offset. */
  recorded: string;
  author?: { id?: string; name?: string; role?: string };
  /** The payload's schema: `type` names the entry type in the source's .d.ts. */
  schema?: { url: string; type: string; sha256: string };
  /** Ids of earlier items from the same issuer that this item replaces entirely. */
  supersedes?: string[];
  /** Ids of earlier items from the same issuer that were entered in error, withdrawn without replacement. */
  retracts?: string[];
  /** Markdown narrative with `<ref id="…">…</ref>` spans; "" if none. */
  narrative: string;
  /** Entry id -> entry, each entry typed by the source's schema; {} if none. */
  payload: Record<string, any>;
}

/** The mapper's entry point. `asOf` is a local date, `YYYY-MM-DD`. */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** Everything one mapper returns for one patient and one source. Empty arrays where the source has nothing. */
export interface ViewRows {
  medications: MedicationRow[];
  problems: ProblemRow[];
  allergies: AllergyIntoleranceRow[];
  labs: LabResultRow[];
  vitals: VitalRow[];
}

/** `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; the precision is the string's length. */
export type PartialDate = string;

/** The items (and entries inside them) a row was built from. At least one. */
export type Evidence = { item_id: string; entry_id?: string }[];

/**
 * Sensitivity categories, for rows whose disclosure a patient may want to control separately.
 * - 'mental-health': behavioral or mental health conditions and the medicines used for them.
 * - 'substance-use': substance use disorders and their treatment.
 * - 'sexual-reproductive-health': sexual and reproductive health, including pregnancy and contraception.
 * - 'hiv-sti': HIV and other sexually transmitted infections.
 * - 'genetic': genetic test results and genetic conditions.
 * Set a category when the source marks the entry restricted or sensitive (map the source's own category,
 * e.g. a behavioral-health restriction is 'mental-health'). You may also set one when the entry plainly
 * belongs to a category. Omit the field when none applies.
 */
export type Sensitivity = 'mental-health' | 'substance-use' | 'sexual-reproductive-health' | 'hiv-sti' | 'genetic';

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Medications
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One outpatient (home) medication as this source records it, with its status as of `asOf`.
 *
 * - One row per drug ingredient. If the source has several lines, orders or prescriptions for the
 *   same ingredient over time (stopped and restarted, re-entered), report the most recent one, i.e.
 *   the one whose own latest event is latest. A line or order that was entered in error, voided or
 *   retracted never existed: do not report it, and do not let it affect another line.
 * - Include medications that are stopped (status 'stopped') if the source still shows them, so the
 *   consumer can say what was stopped and why.
 * - Exclude hospital-only orders (infusions, IV fluids, inpatient-only drugs). They are not home
 *   medications.
 * - When the source publishes a medication list as repeated snapshots (each document or save restates
 *   the list), the latest in-scope snapshot is the source's list; a drug missing from the latest
 *   snapshot is not reported. When the source publishes events or status rows, the latest event or
 *   status row for a line determines its state, however old it is.
 */
export interface MedicationRow {
  /**
   * Generic ingredient name, lower case, without salt or form: "losartan" (not "losartan potassium"),
   * "metformin", "insulin glargine", "empagliflozin". Translate brand names the record uses
   * ("Jardiance" -> "empagliflozin"). Omit only when the record does not say which drug it is (e.g. the
   * patient wrote "water pill").
   */
  ingredient?: string;
  /** RxNorm ingredient CUI, only when the source states an ingredient-level RxNorm code. Never guessed or derived from a product code. */
  rxnorm_ingredient?: string;
  /** The drug as the source names it (display text), e.g. "losartan potassium 50 MG Oral Tablet" or "Jardiance". */
  drug_name: string;
  /**
   * Status as of `asOf`, by this source's account.
   * - 'active': the patient should be taking it (or, on a patient's own list, says they are).
   * - 'held': paused with intent (or at least possibility) of resuming; the patient should not be
   *   taking it now. Not the same as stopped.
   * - 'stopped': discontinued.
   * - 'unknown': the source lists the drug but records no decision about whether it is being taken
   *   (e.g. a hospital list marked as not reconciled).
   * On a patient's own list, a medicine marked as being taken but annotated as paused or stopped for now
   * (e.g. a note "doctor told me to stop for now") is 'held'.
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';
  /**
   * Local date on which the current status began according to this source: for 'held' or 'stopped',
   * the date of the hold or stop; for 'active', the date the source's current line or order started
   * (or resumed). Keep the source's precision. Omit if the source does not say.
   */
  status_since?: PartialDate;
  /**
   * Amount per administration currently prescribed (for 'held' and 'stopped': the amount when it was
   * held or stopped). For a patient's own list: the amount the patient says they take, if they give
   * one; a direction that names no count ("morning", "bedtime") means one tablet or capsule. `unit` is
   * one of the listed units; convert source spellings ("unit", "UNT", "[iU]" -> "units"). Express an
   * amount in tablets as a mass when the record gives the strength per tablet ("200 mg" strength,
   * "take 2" -> 400 mg); use 'tablet' only when the strength is unknown. Omit when the source gives no
   * single amount (a range such as "1 or 2", a sliding scale).
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };
  /**
   * How often, normalized: 'QD' once daily, 'BID' twice daily, 'TID' three times daily, 'QHS' once
   * daily at bedtime, 'QW' once weekly, 'PRN' as needed, 'other' anything else. Omit if unknown.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';
  /**
   * For 'stopped' rows, why, when the source records a coded or clearly stated reason:
   * - 'adverse_reaction': side effect or adverse reaction.
   * - 'ineffective': not working well enough.
   * - 'therapy_changed': replaced by another drug for the same purpose.
   * - 'course_complete': finite course finished.
   * - 'patient_choice': the patient declined or asked to stop.
   * - 'other': another reason (see `status_reason_text`).
   * Omit when the source gives no reason, and on rows that are not 'stopped'.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';
  /** Free-text reason for the current status (hold or stop) as the source wrote it, if any. */
  status_reason_text?: string;
  /** True when the row comes from the patient's own account (a self-reported list), not a clinician's record. */
  patient_reported: boolean;
  /** True when the source says the drug was bought without a prescription. Omit otherwise. */
  otc?: boolean;
  /** See `Sensitivity`. */
  sensitivity?: Sensitivity[];
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Problems
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One condition on the source's problem list (or the source's equivalent: its diagnosis or history
 * lists), with status as of `asOf`.
 *
 * - One row per condition. Several entries for the same condition (re-listed in several documents,
 *   restaged, re-coded) are one row whose fields reflect the latest entry.
 * - Report only conditions the source asserts the patient has or had. Never report a condition that
 *   was ruled out, or one that was only suspected (working/provisional) and never confirmed.
 * - Billing codes attached to a visit or claim are not problem-list entries, unless the source says
 *   its problem list is built from them.
 * - **Drug-caused diagnoses.** A diagnosis the source attributes to a drug (for example "SGLT2
 *   inhibitor-associated ketoacidosis", "ACE i

 *
 * Envelope conventions: `effective` is the time the document is about (ED arrival for an ED note, time
 * of examination for an H&P, progress note or consult, inpatient admission time for a discharge
 * summary, with `effective_end` = discharge time). `author` is the signing clinician. A signed addendum
 * or correction is a new item that `supersedes` the original and restates the whole document.
 */

/** One entry in a Riverside document payload. Discriminated by `type`. */
export type RiversideEntry =
  | Encounter
  | Diagnosis
  | History
  | Allergy
  | HomeMed
  | InpatientMed
  | Vitals
  | Result
  | Panel
  | FollowUp;

/**
 * The encounter and document context. Exactly one per item, conventionally under the key `enc`.
 */
export interface Encounter {
  type: 'encounter';

  /**
   * Riverside encounter number. One number covers the whole hospital stay, from ED arrival to
   * discharge: the ED note, H&P, progress notes, consults and discharge summary of one stay share it.
   */
  encounter_id: string;

  /**
   * Which kind of document this item is.
   * - 'ed_note': emergency department provider note.
   * - 'hp': admission history and physical, written by the admitting physician.
   * - 'progress_note': daily inpatient note.
   * - 'consult': note from a specialty service asked to see the patient.
   * - 'discharge_summary': written at discharge; covers the whole stay. Its home medication list is
   *   the discharge instructions.
   */
  document_kind: 'ed_note' | 'hp' | 'progress_note' | 'consult' | 'discharge_summary';

  /**
   * Encounter class at the time the document was signed.
   * - 'emergency': the patient was in the ED and not yet admitted.
   * - 'inpatient': admitted (including step-down and ICU).
   * A stay that starts in the ED changes class from 'emergency' to 'inpatient' at admission; earlier
   * documents keep the class they were signed with.
   */
  class: 'emergency' | 'inpatient';

  /** Clinical service of the author, free text as configured at Riverside, e.g. "Emergency Medicine", "Hospital Medicine", "Endocrinology". */
  service: string;

  /** ED arrival time, UTC. Present on every document of a stay that began in the ED. */
  arrived?: string;

  /** Inpatient admission order time, UTC. Absent while the patient is still in the ED. */
  admitted?: string;

  /** Discharge time, UTC. Present only on discharge summaries. */
  discharged?: string;

  /**
   * Where the patient went at the end of this phase of care.
   * - 'admitted': ED patient admitted to Riverside (ED notes only).
   * - 'home': discharged home without services.
   * - 'home_with_services': discharged home with home health.
   * - 'transferred': sent to another hospital.
   * - 'left_against_advice': left before the care team discharged them.
   * Absent on H&Ps, progress notes and consults.
   */
  disposition?: 'admitted' | 'home' | 'home_with_services' | 'transferred' | 'left_against_advice';
}

/**
 * A diagnosis on this document's diagnosis list, as the author left it at signing. Diagnoses are
 * re-entered in each document, so the same condition can appear in several items of one stay with
 * different statuses as the workup progresses.
 */
export interface Diagnosis {
  type: 'diagnosis';

  /** Diagnosis as the clinician wrote it, e.g. "R/O pancreatitis", "Euglycemic DKA, SGLT2 inhibitor-associated". */
  label: string;

  /**
   * ICD-10-CM code chosen by the author or added by coding. Absent on working diagnoses entered as free
   * text. An adverse drug effect is coded as its own diagnosis (an ICD-10-CM T-code), not as an
   * allergy.
   */
  icd10cm?: string;

  /**
   * Riverside local diagnosis code, used where ICD-10-CM is too coarse (for example to separate
   * SGLT2 inhibitor-associated euglycemic DKA from other DKA, which share ICD-10-CM E11.10). Code
   * space: Riverside problem dictionary, `RRH-DX-` followed by digits; stable across years.
   */
  riverside_dx?: { code: string; name: string };

  /**
   * Where the diagnosis stood when the document was signed.
   * - 'working': suspected and under evaluation, not established. A later document may confirm it,
   *   rule it out, or silently drop it; an absent later mention does not mean it was confirmed.
   * - 'ruled_out': considered and excluded. The patient does NOT have this condition.
   * - 'active': established and present.
   * - 'resolved': established during this stay and no longer present at signing (e.g. a ketoacidosis
   *   that cleared). The patient had it.
   */
  status: 'working' | 'ruled_out' | 'active' | 'resolved';

  /**
   * - 'principal': the main reason for the hospital stay. Set on H&Ps and discharge summaries only.
   * - 'secondary': any other diagnosis addressed in this document.
   * Absent on ED notes, which do not rank diagnoses.
   */
  rank?: 'principal' | 'secondary';
}

/**
 * A line of past medical history as recorded in this document. Taken from the patient, outside
 * records, or earlier Riverside documents, and not re-verified: stages and dates can be out of date.
 */
export interface History {
  type: 'history';

  /** Condition as written, e.g. "CKD stage 3a", "Type 2 diabetes". */
  condition: string;

  /** ICD-10-CM code if the author picked one from the problem dictionary; often absent. */
  icd10cm?: string;

  /** Onset as written, free text and not normalized: "2016", "~10 years", "childhood". Absent if not stated. */
  onset_text?: string;

  /**
   * Where the line came from.
   * - 'patient': patient or family report.
   * - 'outside_records': another organization's records (e.g. a primary care summary).
   * - 'riverside': an earlier Riverside document.
   */
  source: 'patient' | 'outside_records' | 'riverside';
}

/**
 * An entry on Riverside's allergy list as shown in this document. Riverside keeps one list called
 * "Allergies" and does not separate allergies from intolerances or side effects: a drug that once
 * caused a cough is listed the same way as one that caused anaphylaxis. Read `reaction` to tell them
 * apart. Re-listed in every document.
 */
export interface Allergy {
  type: 'allergy';

  /**
   * Substance as entered, e.g. "lisinopril", "penicillins". If the patient has no known allergies, the
   * list has exactly one entry with substance "NKDA" and no other fields.
   */
  substance: string;

  /** RxNorm ingredient CUI when the substance is a single drug ingredient; absent for classes, foods and "NKDA". */
  rxnorm_ingredient?: string;

  /** Reaction as entered, free text, e.g. "cough", "hives". Absent if unknown. */
  reaction?: string;

  /**
   * Severity as entered.
   * - 'mild': bothersome, not dangerous.
   * - 'moderate': needed treatment or stopping the drug urgently.
   * - 'severe': life-threatening (e.g. anaphylaxis, angioedema).
   * - 'unknown': not recorded.
   */
  severity: 'mild' | 'moderate' | 'severe' | 'unknown';
}

/**
 * One line of the home (outpatient) medication list, with this document's decision about it.
 *
 * The meaning of `status` depends on `document_kind` in the item's `encounter` entry:
 * in ED notes, H&Ps, progress notes and consults it is the plan **during the stay**; in a discharge
 * summary it is the instruction **after discharge**. Only the latest discharge summary of an encounter
 * says what the patient should take at home.
 *
 * Entry keys are chosen per document. They often repeat across the documents of a stay (`med_empa`),
 * but nothing guarantees it: match lines across documents by `rxnorm_ingredient` and `dose_text`, never
 * by key.
 */
export interface HomeMed {
  type: 'home_med';

  /** Drug and form as written on the list, e.g. "empagliflozin 10 mg tablet". */
  drug_name: string;

  /**
   * RxNorm ingredient CUI (not a clinical drug code: strength and form are in `drug_name` and
   * `dose_text`). Absent for combination products and supplements that are not mapped.
   */
  rxnorm_ingredient?: string;

  /** Dose per administration as written, e.g. "1000 mg", "10 units". Text, not normalized. */
  dose_text: string;

  /** Directions as written, e.g. "1 tab PO BID with meals". Not normalized. */
  sig: string;

  /**
   * This document's decision for the drug (see the interface comment for during-stay vs after-discharge).
   * - 'not_reconciled': listed from the patient or prior records; the author made no decision. Typical
   *   of ED notes. Does not mean the patient is taking it now.
   * - 'continue': keep taking (or keep giving in hospital). In a discharge summary this includes a drug
   *   that was held during the stay and is restarted at discharge.
   * - 'held': do not take for now. Not stopped: someone decides later whether to restart, and
   *   `restart_advice` says which way this author leans. `instructions` usually says who decides and
   *   when.
   * - 'stopped': discontinued by this author.
   * - 'new': started during this stay, to continue.
   * - 'changed': same drug, new dose or directions; `dose_text`/`sig` show the new ones.
   */
  status: 'not_reconciled' | 'continue' | 'held' | 'stopped' | 'new' | 'changed';

  /**
   * On 'held' lines only: what this author advises about restarting. Absent on other statuses, and on
   * held lines where the author gave no advice.
   * - 'resume_when_able': restart once the reason for holding has passed (eating again, creatinine back
   *   to baseline). `instructions` usually names the condition.
   * - 'prescriber_decides': no advice either way; the outpatient prescriber decides.
   * - 'advise_against': the author recommends not restarting. The line is held rather than stopped
   *   because the outpatient prescriber makes the final decision. The patient is not taking the drug.
   */
  restart_advice?: 'resume_when_able' | 'prescriber_decides' | 'advise_against';

  /** Free-text instruction attached to the status, e.g. "Do not resume until reviewed by PCP". Absent if none. */
  instructions?: string;
}

/**
 * A medication ordered for use in the hospital only (infusions, IV fluids, inpatient-only drugs).
 * Not part of the home list and not continued after discharge unless it also appears there as 'new'.
 */
export interface InpatientMed {
  type: 'inpatient_med';

  /** Drug or fluid as ordered, e.g. "insulin regular (human) IV infusion", "lactated Ringer's". */
  drug_name: string;

  /** RxNorm ingredient CUI; absent for IV fluids and mixtures. */
  rxnorm_ingredient?: string;

  /** Route as ordered, e.g. "IV", "SubQ", "PO". */
  route: string;

  /** Dose or rate as ordered, free text, e.g. "per DKA protocol, 0.1 units/kg/h", "150 mL/h". */
  dose_text: string;

  /** First administration, UTC. */
  started: string;

  /** Last administration or order discontinue time, UTC. Absent if still running when the document was signed. */
  stopped?: string;
}

/** One set of vital signs taken at one time. Any member may be absent if not measured. */
export interface Vitals {
  type: 'vitals';

  /** When the vitals were taken, UTC. */
  taken: string;

  /** Blood pressure in mmHg. */
  bp?: { systolic_mmhg: number; diastolic_mmhg: number };

  /** Heart rate, beats per minute. */
  heart_rate_bpm?: number;

  /** Respiratory rate, breaths per minute. */
  resp_rate_per_min?: number;

  /** Temperature in degrees Fahrenheit, as entered by nursing. */
  temp_f?: number;

  /** Oxygen saturation by pulse oximetry, percent (0–100). */
  spo2_pct?: number;

  /** Weight in kilograms (converted by the EHR from whatever unit was entered). */
  weight_kg?: number;
}

/**
 * The value part of a lab result. Used on its own as `Result` and for each component of a `Panel`.
 */
export interface ResultValue {
  /**
   * Riverside lab test. `local_code` is the Riverside lab dictionary code (stable across years).
   * `loinc` is present for most chemistry and hematology tests and absent for some point-of-care and
   * send-out tests (e.g. beta-hydroxybutyrate). `name` is the display name.
   */
  test: { local_code: string; loinc?: string; name: string };

  /**
   * Result exactly as displayed by the lab, as text. Usually a decimal number (`"182"`, `"7.21"`), but
   * may carry a comparator (`"<0.01"`, `">600"`) or be words (`"Hemolyzed, see comment"`). Parse with
   * care; a comparator means the true value is beyond the reportable limit.
   */
  value: string;

  /**
   * Unit as the lab reports it, close to UCUM: "mg/dL", "mmol/L", "U/L", "ng/mL", "10*3/uL" (thousands
   * per microliter), "g/dL", "mmHg", "mL/min/1.73m2". Absent for unitless results (pH).
   */
  unit?: string;

  /** Reference range as displayed, text, in the same unit as `value`, e.g. "70-99", "<0.04". Absent if the lab gives none. */
  ref_range?: string;

  /**
   * Abnormal flag from the lab.
   * - 'H' / 'L': above / below the reference range.
   * - 'HH' / 'LL': critically high / low.
   * - 'A': abnormal, no direction (non-numeric results).
   * Absent when the value is within range.
   */
  flag?: 'H' | 'L' | 'HH' | 'LL' | 'A';
}

/**
 * Copy of one lab result reviewed in this document. The same result (same `accession` and
 * `test.local_code`) can appear in several documents; it is one result, not several.
 */
export interface Result extends ResultValue {
  type: 'result';

  /** Riverside lab accession number for the specimen. With `test.local_code` it identifies the result. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /**
   * Status of the result when this document copied it.
   * - 'preliminary': reported but not verified; may change.
   * - 'final': verified.
   * - 'corrected': a final value that the lab later changed; `value` is the corrected value.
   * A document never updates after signing, so a later document can show a different status or value
   * for the same result. Use the copy with the most advanced status.
   */
  status: 'preliminary' | 'final' | 'corrected';
}

/**
 * Copy of a panel of results from one specimen (basic metabolic panel, CBC, blood gas). Components carry
 * their own codes, values and flags; the panel carries what they share. Same duplication rules as
 * `Result`.
 */
export interface Panel {
  type: 'panel';

  /** Riverside panel order code and name, e.g. { local_code: "BMP", name: "Basic metabolic panel" }. LOINC present when the panel has one. */
  panel: { local_code: string; loinc?: string; name: string };

  /** Riverside lab accession number for the specimen. */
  accession: string;

  /** Specimen collection time, UTC. */
  collected: string;

  /** Specimen as labelled by the lab, e.g. "serum", "venous blood", "whole blood". */
  specimen: string;

  /** Status of the panel as a whole when copied; same values and meaning as `Result.status`. */
  status: 'preliminary' | 'final' | 'corrected';

  /**
   * Component results, in the lab's display order. Includes computed values the lab reports with the
   * panel (anion gap, eGFR). eGFR at Riverside is CKD-EPI 2021 (race-free) for all results since 2023.
   */
  components: ResultValue[];
}

/** A follow-up the author arranged or recommended. Mostly in discharge summaries. */
export interface FollowUp {
  type: 'follow_up';

  /** Clinician, clinic or service to follow up with, as written, e.g. "Primary care (Northgate Family Medicine)". */
  with: string;

  /** When, as written, e.g. "within 1 week", "2024-11-12". Not normalized. */
  when_text: string;

  /** What the follow-up is for, free text. */
  purpose: string;
}
/**
 * Consumer views, version 2: the small shapes a patient-facing chart app reads.
 *
 * These are defined by the consumer, not by any source. A mapper turns one source's FOLIO record items
 * for one patient into these rows. The consumer merges rows from several sources itself, so a mapper
 * reports only what its own source says, and never invents, infers from other sources, or "corrects"
 * what the source records.
 *
 * Contract (see `Transform`): the mapper receives every item one source published for one patient,
 * in no particular order and including items that were later superseded or retracted, plus an
 * `asOf` date. It returns the rows that describe that source's record as it stood at the end of that
 * date.
 *
 * Conventions for every view:
 *
 * - **Scope in time.** An item is in scope when its envelope `recorded` time is on or before the end of
 *   the `asOf` day in America/Chicago. Ignore items recorded later. Apply the FOLIO correction rules to
 *   the items in scope: an item listed in another in-scope item's `supersedes` or `retracts` (same
 *   issuer) is not current; supersession is transitive. Use only current items, except where a view
 *   below says otherwise.
 * - **Time zone.** The consumer displays everything in America/Chicago, the patients' home zone. "Local
 *   date" and "local time" below mean wall-clock date/time in America/Chicago (UTC-6 standard, UTC-5
 *   daylight time). A date-time with no offset and no zone (for example a phone's wall clock) is taken to
 *   be America/Chicago local time: report it as written, do not shift it, and do not leave it out.
 * - **Partial dates.** `PartialDate` strings keep the precision the source actually knows: "2016"
 *   means some time in 2016, never 2016-01-01. Never pad a year-only or month-only date.
 * - **Only what the source records.** Rows come from structured payload entries. Narrative text may be
 *   used to understand an entry but must not be the only basis for a row.
 * - **Evidence.** Every row lists the items (and payload entry ids) it was built from, so the consumer
 *   can show the source text behind a fact. Cite at least the item whose entry gives the row's current
 *   state.
 * - **Sensitive entries are reported, never dropped.** Report every entry the source holds, including
 *   ones it marks restricted, confidential or sensitive. Mark such rows with `sensitivity` (see
 *   `Sensitivity`). Whether a sensitive fact is shown or shared is decided later, by the patient, at
 *   disclosure time; it is never decided by a mapper.
 * - **Determinism.** Same input, same output: no clock, randomness, network or file access.
 */

/** A FOLIO record item in its JSON form (see the FOLIO record-item spec). */
export interface FolioItem {
  folio: string;
  /** Item id (ULID), unique within the issuer. */
  id: string;
  /** did:web of the issuing organization. */
  issuer: string;
  /** Patient id at this issuer. */
  patient: string;
  /** When the clinical event happened: RFC 3339 date-time with offset, or a full or partial date. */
  effective: string;
  effective_end?: string;
  /** When the issuer committed this item: RFC 3339 date-time with offset. */
  recorded: string;
  author?: { id?: string; name?: string; role?: string };
  /** The payload's schema: `type` names the entry type in the source's .d.ts. */
  schema?: { url: string; type: string; sha256: string };
  /** Ids of earlier items from the same issuer that this item replaces entirely. */
  supersedes?: string[];
  /** Ids of earlier items from the same issuer that were entered in error, withdrawn without replacement. */
  retracts?: string[];
  /** Markdown narrative with `<ref id="…">…</ref>` spans; "" if none. */
  narrative: string;
  /** Entry id -> entry, each entry typed by the source's schema; {} if none. */
  payload: Record<string, any>;
}

/** The mapper's entry point. `asOf` is a local date, `YYYY-MM-DD`. */
export type Transform = (items: FolioItem[], asOf: string) => ViewRows;

/** Everything one mapper returns for one patient and one source. Empty arrays where the source has nothing. */
export interface ViewRows {
  medications: MedicationRow[];
  problems: ProblemRow[];
  allergies: AllergyIntoleranceRow[];
  labs: LabResultRow[];
  vitals: VitalRow[];
}

/** `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; the precision is the string's length. */
export type PartialDate = string;

/** The items (and entries inside them) a row was built from. At least one. */
export type Evidence = { item_id: string; entry_id?: string }[];

/**
 * Sensitivity categories, for rows whose disclosure a patient may want to control separately.
 * - 'mental-health': behavioral or mental health conditions and the medicines used for them.
 * - 'substance-use': substance use disorders and their treatment.
 * - 'sexual-reproductive-health': sexual and reproductive health, including pregnancy and contraception.
 * - 'hiv-sti': HIV and other sexually transmitted infections.
 * - 'genetic': genetic test results and genetic conditions.
 * Set a category when the source marks the entry restricted or sensitive (map the source's own category,
 * e.g. a behavioral-health restriction is 'mental-health'). You may also set one when the entry plainly
 * belongs to a category. Omit the field when none applies.
 */
export type Sensitivity = 'mental-health' | 'substance-use' | 'sexual-reproductive-health' | 'hiv-sti' | 'genetic';

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Medications
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One outpatient (home) medication as this source records it, with its status as of `asOf`.
 *
 * - One row per drug ingredient. If the source has several lines, orders or prescriptions for the
 *   same ingredient over time (stopped and restarted, re-entered), report the most recent one, i.e.
 *   the one whose own latest event is latest. A line or order that was entered in error, voided or
 *   retracted never existed: do not report it, and do not let it affect another line.
 * - Include medications that are stopped (status 'stopped') if the source still shows them, so the
 *   consumer can say what was stopped and why.
 * - Exclude hospital-only orders (infusions, IV fluids, inpatient-only drugs). They are not home
 *   medications.
 * - When the source publishes a medication list as repeated snapshots (each document or save restates
 *   the list), the latest in-scope snapshot is the source's list; a drug missing from the latest
 *   snapshot is not reported. When the source publishes events or status rows, the latest event or
 *   status row for a line determines its state, however old it is.
 */
export interface MedicationRow {
  /**
   * Generic ingredient name, lower case, without salt or form: "losartan" (not "losartan potassium"),
   * "metformin", "insulin glargine", "empagliflozin". Translate brand names the record uses
   * ("Jardiance" -> "empagliflozin"). Omit only when the record does not say which drug it is (e.g. the
   * patient wrote "water pill").
   */
  ingredient?: string;
  /** RxNorm ingredient CUI, only when the source states an ingredient-level RxNorm code. Never guessed or derived from a product code. */
  rxnorm_ingredient?: string;
  /** The drug as the source names it (display text), e.g. "losartan potassium 50 MG Oral Tablet" or "Jardiance". */
  drug_name: string;
  /**
   * Status as of `asOf`, by this source's account.
   * - 'active': the patient should be taking it (or, on a patient's own list, says they are).
   * - 'held': paused with intent (or at least possibility) of resuming; the patient should not be
   *   taking it now. Not the same as stopped.
   * - 'stopped': discontinued.
   * - 'unknown': the source lists the drug but records no decision about whether it is being taken
   *   (e.g. a hospital list marked as not reconciled).
   * On a patient's own list, a medicine marked as being taken but annotated as paused or stopped for now
   * (e.g. a note "doctor told me to stop for now") is 'held'.
   */
  status: 'active' | 'held' | 'stopped' | 'unknown';
  /**
   * Local date on which the current status began according to this source: for 'held' or 'stopped',
   * the date of the hold or stop; for 'active', the date the source's current line or order started
   * (or resumed). Keep the source's precision. Omit if the source does not say.
   */
  status_since?: PartialDate;
  /**
   * Amount per administration currently prescribed (for 'held' and 'stopped': the amount when it was
   * held or stopped). For a patient's own list: the amount the patient says they take, if they give
   * one; a direction that names no count ("morning", "bedtime") means one tablet or capsule. `unit` is
   * one of the listed units; convert source spellings ("unit", "UNT", "[iU]" -> "units"). Express an
   * amount in tablets as a mass when the record gives the strength per tablet ("200 mg" strength,
   * "take 2" -> 400 mg); use 'tablet' only when the strength is unknown. Omit when the source gives no
   * single amount (a range such as "1 or 2", a sliding scale).
   */
  dose?: { value: number; unit: 'mg' | 'mcg' | 'units' | 'mL' | 'tablet' };
  /**
   * How often, normalized: 'QD' once daily, 'BID' twice daily, 'TID' three times daily, 'QHS' once
   * daily at bedtime, 'QW' once weekly, 'PRN' as needed, 'other' anything else. Omit if unknown.
   */
  frequency?: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other';
  /**
   * For 'stopped' rows, why, when the source records a coded or clearly stated reason:
   * - 'adverse_reaction': side effect or adverse reaction.
   * - 'ineffective': not working well enough.
   * - 'therapy_changed': replaced by another drug for the same purpose.
   * - 'course_complete': finite course finished.
   * - 'patient_choice': the patient declined or asked to stop.
   * - 'other': another reason (see `status_reason_text`).
   * Omit when the source gives no reason, and on rows that are not 'stopped'.
   */
  stop_reason?: 'adverse_reaction' | 'ineffective' | 'therapy_changed' | 'course_complete' | 'patient_choice' | 'other';
  /** Free-text reason for the current status (hold or stop) as the source wrote it, if any. */
  status_reason_text?: string;
  /** True when the row comes from the patient's own account (a self-reported list), not a clinician's record. */
  patient_reported: boolean;
  /** True when the source says the drug was bought without a prescription. Omit otherwise. */
  otc?: boolean;
  /** See `Sensitivity`. */
  sensitivity?: Sensitivity[];
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Problems
// ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * One condition on the source's problem list (or the source's equivalent: its diagnosis or history
 * lists), with status as of `asOf`.
 *
 * - One row per condition. Several entries for the same condition (re-listed in several documents,
 *   restaged, re-coded) are one row whose fields reflect the latest entry.
 * - Report only conditions the source asserts the patient has or had. Never report a condition that
 *   was ruled out, or one that was only suspected (working/provisional) and never confirmed.
 * - Billing codes attached to a visit or claim are not problem-list entries, unless the source says
 *   its problem list is built from them.
 * - **Drug-caused diagnoses.** A diagnosis the source attributes to a drug (for example "SGLT2
 *   inhibitor-associated ketoacidosis", "ACE inhibitor-associated angioedema", or an ICD-10 T-code
 *   "adverse effect of …" entry) yields an `AllergyIntoleranceRow` for the drug (see there) in addition
 *   to a ProblemRow for the condition it caused. A T-code entry that names only the adverse effect and no
 *   condition yields the AllergyIntoleranceRow alone.
 */
export interface ProblemRow {
  /** The condition as the source words it, e.g. "Chronic kidney disease stage 3a". */
  condition: string;
  /** ICD-10-CM code, with the dot, as the source gives it (latest). Omit if the source gives none. */
  icd10cm?: string;
  /** SNOMED CT concept id, if the source gives one. */
  snomed?: string;
  /**
   * - 'active': the patient has it.
   * - 'resolved': the patient had it and the source says it is resolved or historical.
   */
  status: 'active' | 'resolved';
  /** When the condition began, at the precision the source knows. Omit if the source does not say. */
  onset?: { value: PartialDate; precision: 'year' | 'month' | 'day' };
  /**
   * For chronic kidney disease only: the KDIGO GFR category the source most recently recorded for this
   * patient ('G3a' for "stage 3a", "N18.31" or a G3a category field). As recorded by a clinician; never
   * computed from lab values.
   */
  ckd_stage?: 'G1' | 'G2' | 'G3a' | 'G3b' | 'G4' | 'G5';
  /** For chronic kidney disease only: KDIGO albuminuria category as recorded ('A1', 'A2', 'A3'), if the source records one. */
  albuminuria?: 'A1' | 'A2' | 'A3';
  /** See `Sensitivity`. */
  sensitivity?: Sensitivity[];
  evidence: Evidence;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Allergies, intolerances, adverse reactions

import type {
  FolioItem, ViewRows, MedicationRow, ProblemRow, AllergyIntoleranceRow, LabResultRow, VitalRow,
  Evidence, Analyte, Sensitivity,
} from "../in/views/views";

const TZ = "America/Chicago";

function parts(ms: number): Record<string, string> {
  const f = new Intl.DateTimeFormat("en-US", {
    timeZone: TZ, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit",
  });
  const o: Record<string, string> = {};
  for (const p of f.formatToParts(new Date(ms))) o[p.type] = p.value;
  return o;
}
function localDate(iso: string | undefined): string | undefined {
  if (!iso) return undefined;
  if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
  const ms = Date.parse(iso);
  if (isNaN(ms)) return undefined;
  const p = parts(ms);
  return `${p.year}-${p.month}-${p.day}`;
}
function localMinute(iso: string): string | undefined {
  const ms = Date.parse(iso);
  if (isNaN(ms)) return undefined;
  const p = parts(ms);
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;
}
function ms(iso: string | undefined): number {
  const v = iso ? Date.parse(iso) : NaN;
  return isNaN(v) ? 0 : v;
}

interface Doc {
  item: FolioItem;
  enc: any;
  kind: string;
  encId: string;
  time: number; // clinical time used for ordering
  entries: [string, any][];
}

function entriesOf(item: FolioItem): [string, any][] {
  const out: [string, any][] = [];
  const p = item && item.payload;
  if (p && typeof p === "object") for (const k of Object.keys(p)) if (p[k] && typeof p[k] === "object") out.push([k, p[k]]);
  return out;
}

function buildDocs(items: FolioItem[], asOf: string): Doc[] {
  const inScope = items.filter((i) => {
    const d = localDate(i && i.recorded);
    return d !== undefined && d <= asOf;
  });
  const dead = new Set<string>();
  for (const i of inScope) {
    for (const id of i.supersedes ?? []) dead.add(id);
    for (const id of i.retracts ?? []) dead.add(id);
  }
  const docs: Doc[] = [];
  for (const item of inScope) {
    if (dead.has(item.id)) continue;
    const entries = entriesOf(item);
    const enc = entries.map((e) => e[1]).find((e) => e.type === "encounter") ?? {};
    const kind = enc.document_kind ?? "";
    const time = kind === "discharge_summary" ? ms(enc.discharged ?? item.effective_end ?? item.effective) : ms(item.effective);
    docs.push({ item, enc, kind, encId: enc.encounter_id ?? "", time, entries });
  }
  docs.sort((a, b) => a.time - b.time || ms(a.item.recorded) - ms(b.item.recorded) || (a.item.id < b.item.id ? -1 : 1));
  return docs;
}

// ───────────── medications ─────────────

const SALTS = new Set(["potassium", "sodium", "hydrochloride", "hcl", "sulfate", "succinate", "tartrate", "maleate", "besylate",
  "mesylate", "calcium", "phosphate", "acetate", "citrate", "fumarate", "bromide", "magnesium", "hydrobromide", "disoproxil"]);
const FORMS = new Set(["tablet", "tablets", "capsule", "capsules", "oral", "solution", "injection", "pen", "extended", "release",
  "er", "xr", "sr", "dr", "delayed", "chewable", "suspension", "cream", "ointment", "inhaler", "patch", "pack", "syringe", "vial"]);
const BRANDS: Record<string, string> = {
  jardiance: "empagliflozin", farxiga: "dapagliflozin", invokana: "canagliflozin", glucophage: "metformin",
  cozaar: "losartan", zestril: "lisinopril", prinivil: "lisinopril", lantus: "insulin glargine", toujeo: "insulin glargine",
  basaglar: "insulin glargine", levemir: "insulin detemir", novolog: "insulin aspart", humalog: "insulin lispro",
  lasix: "furosemide", norvasc: "amlodipine", lipitor: "atorvastatin", zocor: "simvastatin", crestor: "rosuvastatin",
  tylenol: "acetaminophen", aleve: "naproxen", advil: "ibuprofen", motrin: "ibuprofen", januvia: "sitagliptin",
  ozempic: "semaglutide", victoza: "liraglutide", trulicity: "dulaglutide", coumadin: "warfarin", eliquis: "apixaban",
};

function ingredientName(drug: string): string | undefined {
  const toks = String(drug ?? "").toLowerCase().replace(/[(),]/g, " ").split(/\s+/).filter(Boolean);
  const keep: string[] = [];
  for (const t of toks) {
    if (/^\d/.test(t) || t === "mg" || t === "mcg" || t === "units") break;
    keep.push(t);
  }
  while (keep.length > 1 && (SALTS.has(keep[keep.length - 1]) || FORMS.has(keep[keep.length - 1]))) keep.pop();
  while (keep.length > 1 && FORMS.has(keep[keep.length - 1])) keep.pop();
  if (!keep.length) return undefined;
  const name = keep.join(" ");
  return BRANDS[name] ?? BRANDS[keep[0]] ?? name;
}

function parseDose(text: string, drug: string): MedicationRow["dose"] | undefined {
  const t = String(text ?? "").toLowerCase().trim();
  if (/\bor\b|-|–|to/.test(t.replace(/^[\d.]+\s*[a-z\[\]]+$/, ""))) {
    if (!/^[\d.,]+\s*(mg|mcg|ug|units?|ml|\[iu\]|unt|g)\b/.test(t)) return undefined;
  }
  const m = t.match(/^([\d]+(?:\.\d+)?)\s*(mg|mcg|ug|g|units?|unt|\[iu\]|iu|ml|tablets?|tabs?|capsules?|caps?)\b/);
  if (!m) return undefined;
  const v = parseFloat(m[1]);
  const u = m[2];
  if (u === "mg") return { value: v, unit: "mg" };
  if (u === "mcg" || u === "ug") return { value: v, unit: "mcg" };
  if (u === "g") return { value: v * 1000, unit: "mg" };
  if (u === "ml") return { value: v, unit: "mL" };
  if (/^(unit|units|unt|\[iu\]|iu)$/.test(u)) return { value: v, unit: "units" };
  // tablets / capsules: use strength from drug name if known
  const s = String(drug ?? "").toLowerCase().match(/(\d+(?:\.\d+)?)\s*(mg|mcg)\b/);
  if (s) return { value: v * parseFloat(s[1]), unit: s[2] as "mg" | "mcg" };
  return { value: v, unit: "tablet" };
}

function parseFreq(sig: string): MedicationRow["frequency"] | undefined {
  const s = String(sig ?? "").toLowerCase();
  if (!s) return undefined;
  if (/\bprn\b|as needed/.test(s)) return "PRN";
  if (/\bqhs\b|bedtime|at night|\bhs\b/.test(s)) return "QHS";
  if (/\bbid\b|twice|2 times|two times|b\.i\.d|every 12/.test(s)) return "BID";
  if (/\btid\b|three times|3 times|t\.i\.d|every 8 h/.test(s)) return "TID";
  if (/\bqw\b|weekly|once a week|every week|per week/.test(s)) return "QW";
  if (/\bqd\b|\bdaily\b|once a day|every day|\bqam\b|every morning|each morning|once daily|\bod\b|in the morning/.test(s)) return "QD";
  return "other";
}

function stopReason(text: string | undefined): MedicationRow["stop_reason"] | undefined {
  const s = (text ?? "").toLowerCase();
  if (!s) return undefined;
  if (/cough|side effect|adverse|reaction|angioedema|rash|hives|intoleran|ketoacidosis|hyperkal|toxicity/.test(s)) return "adverse_reaction";
  if (/ineffective|not working|inadequate|no benefit|failure/.test(s)) return "ineffective";
  if (/replaced|switch|changed to|instead of/.test(s)) return "therapy_changed";
  if (/course (complete|finished)|completed/.test(s)) return "course_complete";
  if (/patient (declin|request|choice|prefer)|declined/.test(s)) return "patient_choice";
  return "other";
}

const MH = new Set(["sertraline", "fluoxetine", "citalopram", "escitalopram", "paroxetine", "bupropion", "venlafaxine", "duloxetine",
  "mirtazapine", "trazodone", "quetiapine", "olanzapine", "risperidone", "aripiprazole", "lithium", "lamotrigine", "buspirone",
  "alprazolam", "lorazepam", "clonazepam", "diazepam", "amitriptyline", "nortriptyline", "haloperidol", "lurasidone"]);
const SU = new Set(["buprenorphine", "naltrexone", "methadone", "disulfiram", "acamprosate", "naloxone"]);

function medKey(m: any): string {
  return m.rxnorm_ingredient ? "rx:" + m.rxnorm_ingredient : "nm:" + (ingredientName(m.drug_name) ?? String(m.drug_name).toLowerCase());
}

function buildMeds(docs: Doc[]): MedicationRow[] {
  const withEnc = docs.filter((d) => d.entries.some((e) => e[1].type === "home_med"));
  if (!withEnc.length) return [];
  const latest = withEnc[withEnc.length - 1];
  const sameEnc = withEnc.filter((d) => d.encId === latest.encId);
  const summaries = sameEnc.filter((d) => d.kind === "discharge_summary");
  const chosen = summaries.length ? summaries[summaries.length - 1] : sameEnc[sameEnc.length - 1];
  const prior = sameEnc.filter((d) => d !== chosen && d.time <= chosen.time && d.kind !== "discharge_summary");

  const byKey = new Map<string, [string, any]>();
  for (const [id, e] of chosen.entries) if (e.type === "home_med") byKey.set(medKey(e), [id, e]);

  const rows: MedicationRow[] = [];
  for (const [key, [id, e]] of byKey) {
    const evidence: Evidence = [{ item_id: chosen.item.id, entry_id: id }];
    const st: string = e.status;
    const status: MedicationRow["status"] =
      st === "held" ? "held" : st === "stopped" ? "stopped" : st === "not_reconciled" ? "unknown" : "active";
    const chosenDate = chosen.kind === "discharge_summary"
      ? localDate(chosen.enc.discharged ?? chosen.item.effective_end) : localDate(chosen.item.effective);

    // history of this line within the stay (earlier documents, oldest first)
    const hist: { doc: Doc; id: string; st: string }[] = [];
    for (const d of prior) for (const [pid, pe] of d.entries) if (pe.type === "home_med" && medKey(pe) === key) hist.push({ doc: d, id: pid, st: pe.status });
    let since: string | undefined;
    const docDate = (d: Doc) => localDate(d.item.effective);
    if (status === "held" || status === "stopped") {
      let first: { doc: Doc; id: string } | undefined;
      for (let i = hist.length - 1; i >= 0; i--) {
        if (hist[i].st === st) first = hist[i]; else break;
      }
      if (first) { since = docDate(first.doc); evidence.push({ item_id: first.doc.item.id, entry_id: first.id }); }
      else since = chosenDate;
    } else if (status === "active") {
      const prev = hist.length ? hist[hist.length - 1].st : undefined;
      if (st === "new" || st === "changed") {
        let first: { doc: Doc; id: string } | undefined;
        for (let i = hist.length - 1; i >= 0; i--) {
          if (hist[i].st === st) first = hist[i]; else break;
        }
        if (first) { since = docDate(first.doc); evidence.push({ item_id: first.doc.item.id, entry_id: first.id }); }
        else since = chosenDate;
      } else if (prev === "held" || prev === "stopped") since = chosenDate;
    } else {
      // unknown
    }

    const ingredient = ingredientName(e.drug_name);
    const row: MedicationRow = {
      ...(ingredient ? { ingredient } : {}),
      ...(e.rxnorm_ingredient ? { rxnorm_ingredient: String(e.rxnorm_ingredient) } : {}),
      drug_name: String(e.drug_name),
      status,
      patient_reported: false,
      evidence,
    };
    if (since) row.status_since = since;
    const dose = parseDose(e.dose_text, e.drug_name);
    if (dose) row.dose = dose;
    const fr = parseFreq(e.sig);
    if (fr) row.frequency = fr;
    if (status === "stopped") {
      const sr = stopReason(e.instructions);
      if (sr) row.stop_reason = sr;
    }
    if ((status === "held" || status === "stopped") && e.instructions) row.status_reason_text = String(e.instructions);
    if (ingredient) {
      const s: Sensitivity[] = [];
      if (MH.has(ingredient)) s.push("mental-health");
      if (SU.has(ingredient)) s.push("substance-use");
      if (s.length) row.sensitivity = s;
    }
    rows.push(row);
  }
  return rows;
}

// ───────────── problems & drug-caused diagnoses ─────────────

const CLASSES: { re: RegExp; name: string; members: string[]; nonImmune?: boolean }[] = [
  { re: /sglt-?2/i, name: "SGLT2 inhibitor", members: ["empagliflozin", "dapagliflozin", "canagliflozin", "ertugliflozin", "sotagliflozin"], nonImmune: true },
  { re: /ace[\s-]*inhibitor|angiotensin[- ]converting/i, name: "ACE inhibitor", members: ["lisinopril", "enalapril", "ramipril", "benazepril", "captopril", "quinapril", "fosinopril", "perindopril", "trandolapril"], nonImmune: true },
  { re: /\bstatin/i, name: "statin", members: ["atorvastatin", "simvastatin", "rosuvastatin", "pravastatin", "lovastatin", "pitavastatin"] },
  { re: /\barb\b|angiotensin receptor/i, name: "angiotensin receptor blocker", members: ["losartan", "valsartan", "irbesartan", "olmesartan", "candesartan", "telmisartan"] },
  { re: /sulfonylurea/i, name: "sulfonylurea", members: ["glipizide", "glyburide", "glimepiride"] },
  { re: /nsaid|anti-?inflammatory/i, name: "NSAID", members: ["ibuprofen", "naproxen", "diclofenac", "meloxicam", "celecoxib"] },
  { re: /thiazide/i, name: "thiazide diuretic", members: ["hydrochlorothiazide", "chlorthalidone"] },
  { re: /beta[- ]?blocker/i, name: "beta blocker", members: ["metoprolol", "atenolol", "carvedilol", "propranolol"] },
  { re: /\bpenicillin/i, name: "penicillin", members: ["amoxicillin", "penicillin"] },
];
const KNOWN_DRUGS = ["empagliflozin", "dapagliflozin", "canagliflozin", "metformin", "lisinopril", "enalapril", "ramipril", "losartan",
  "hydrochlorothiazide", "naproxen", "ibuprofen", "atorvastatin", "simvastatin", "rosuvastatin", "amoxicillin", "penicillin",
  "furosemide", "spironolactone", "insulin glargine", "glipizide", "sitagliptin", "warfarin", "apixaban", "amlodipine"];

function normLabel(s: string): string {
  return String(s ?? "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}
function isCkd(label: string, icd?: string): boolean {
  return /chronic kidney|\bckd\b/i.test(label) || /^N18\./i.test(icd ?? "");
}
function ckdStageOf(label: string, icd?: string): ProblemRow["ckd_stage"] | undefined {
  const l = label.toLowerCase();
  const m = l.match(/\bg\s?([1-5])\s?(a|b)?\b/) ;
  if (m) { if (m[1] === "3") return m[2] === "b" ? "G3b" : m[2] === "a" ? "G3a" : undefined; return ("G" + m[1]) as ProblemRow["ckd_stage"]; }
  const s = l.match(/stage\s*(1|2|3\s*a|3\s*b|3|4|5|i{1,3}v?|iv|v)\b/);
  if (s) {
    const v = s[1].replace(/\s/g, "");
    if (v === "3a") return "G3a"; if (v === "3b") return "G3b";
    if (v === "1") return "G1"; if (v === "2") return "G2"; if (v === "4") return "G4"; if (v === "5") return "G5";
  }
  const c = (icd ?? "").toUpperCase();
  const map: Record<string, ProblemRow["ckd_stage"]> = { "N18.1": "G1", "N18.2": "G2", "N18.31": "G3a", "N18.32": "G3b", "N18.4": "G4", "N18.5": "G5" };
  return map[c];
}
function albuminuriaOf(label: string): ProblemRow["albuminuria"] | undefined {
  const m = label.match(/\bA([1-3])\b/);
  return m ? (("A" + m[1]) as ProblemRow["albuminuria"]) : undefined;
}
function parseOnset(t: string | undefined): ProblemRow["onset"] | undefined {
  const s = (t ?? "").trim();
  if (/^\d{4}$/.test(s)) return { value: s, precision: "year" };
  if (/^\d{4}-\d{2}$/.test(s)) return { value: s, precision: "month" };
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return { value: s, precision: "day" };
  return undefined;
}

interface DxEntry { doc: Doc; id: string; e: any; }

function drugCaused(e: any): { tcode: boolean; text: string } | undefined {
  const label = String(e.label ?? "");
  const icd = String(e.icd10cm ?? "").toUpperCase();
  const t = /^T(3[6-9]|4\d|50)\.[0-9A-Z]*5[A-Z]?$/.test(icd) || /^T(3[6-9]|4\d|50)\.\w*5/.test(icd);
  if (t) return { tcode: !/ketoacidosis|angioedema|hyperkal|acidosis|rash|cough|injury|failure/i.test(label), text: label };
  if (/associated|induced|adverse (effect|reaction) of|due to .*(inhibitor|drug)|caused by/i.test(label) &&
      (CLASSES.some((c) => c.re.test(label)) || KNOWN_DRUGS.some((d) => label.toLowerCase().includes(d)) || /adverse (effect|reaction)/i.test(label)))
    return { tcode: /^adverse (effect|reaction)/i.test(label), text: label };
  return undefined;
}

function buildProblemsAndDxAllergies(docs: Doc[]): { problems: ProblemRow[]; dxAllergies: AllergyIntoleranceRow[] } {
  const groups = new Map<string, { dx: DxEntry[]; hist: DxEntry[] }>();
  const keyFor = (label: string, icd: string | undefined, rdx: any): string => {
    if (isCkd(label, icd)) return "ckd";
    if (rdx && rdx.code) return "rdx:" + rdx.code;
    if (icd) {
      const set = rdxByIcd.get(icd.toUpperCase());
      if (set && set.size === 1) return "rdx:" + [...set][0];
      return "icd:" + icd.toUpperCase();
    }
    return "lbl:" + normLabel(label);
  };
  const rdxByIcd = new Map<string, Set<string>>();
  for (const d of docs) for (const [, e] of d.entries) {
    if (e.type === "diagnosis" && e.icd10cm && e.riverside_dx && e.riverside_dx.code) {
      const k = String(e.icd10cm).toUpperCase();
      const set = rdxByIcd.get(k) ?? new Set<string>();
      set.add(e.riverside_dx.code); rdxByIcd.set(k, set);
    }
  }
  const dxAllergies: AllergyIntoleranceRow[] = [];
  const seenAllergy = new Map<string, AllergyIntoleranceRow>();

  for (const d of docs) {
    for (const [id, e] of d.entries) {
      if (e.type === "diagnosis" && e.label) {
        const k = keyFor(e.label, e.icd10cm, e.riverside_dx);
        const g = groups.get(k) ?? { dx: [], hist: [] };
        g.dx.push({ doc: d, id, e }); groups.set(k, g);
      } else if (e.type === "history" && e.condition) {
        const k = keyFor(e.condition, e.icd10cm, undefined);
        const g = groups.get(k) ?? { dx: [], hist: [] };
        g.hist.push({ doc: d, id, e }); groups.set(k, g);
      }
    }
  }

  const problems: ProblemRow[] = [];
  for (const [k, g] of groups) {
    // status from diagnoses (established ones), else history
    const est = g.dx.filter((x) => x.e.status !== "working");
    let status: "active" | "resolved" | undefined;
    let cur: DxEntry | undefined;
    let label = "";
    let icd: string | undefined;
    if (est.length) {
      cur = est[est.length - 1];
      if (cur.e.status === "ruled_out") continue;
      status = cur.e.status === "resolved" ? "resolved" : "active";
      label = cur.e.label; icd = cur.e.icd10cm;
    } else if (g.hist.length) {
      if (g.dx.length) continue; // only working diagnoses plus history: history line stands? keep it below
    }
    if (!cur) {
      if (!g.hist.length) continue;
      cur = g.hist[g.hist.length - 1];
      status = "active";
      label = cur.e.condition; icd = cur.e.icd10cm;
    }
    // drug-caused? (handled separately, but T-code-only entries yield no problem row)
    const dc = g.dx.length && cur.e.type === "diagnosis" ? drugCaused(cur.e) : undefined;
    if (dc && dc.tcode) continue;

    const all = [...g.dx.filter((x) => x.e.status !== "working" && x.e.status !== "ruled_out"), ...g.hist]
      .sort((a, b) => a.doc.time - b.doc.time);
    // latest icd among entries that carry one
    for (let i = all.length - 1; i >= 0 && !icd; i--) icd = all[i].e.icd10cm;
    const row: ProblemRow = { condition: label, status: status!, evidence: [{ item_id: cur.doc.item.id, entry_id: cur.id }] };
    if (icd) row.icd10cm = icd;
    // onset from the latest history line that states one
    for (let i = g.hist.length - 1; i >= 0; i--) {
      const o = parseOnset(g.hist[i].e.onset_text);
      if (o) { row.onset = o; break; }
    }
    if (k === "ckd") {
      for (let i = all.length - 1; i >= 0; i--) {
        const x = all[i].e;
        const lab = String(x.label ?? x.condition ?? "");
        const st = ckdStageOf(lab, x.icd10cm);
        if (st) { row.ckd_stage = st; break; }
      }
      for (let i = all.length - 1; i >= 0; i--) {
        const x = all[i].e;
        const a = albuminuriaOf(String(x.label ?? x.condition ?? ""));
        if (a) { row.albuminuria = a; break; }
      }
    }
    problems.push(row);
  }

  // drug-caused diagnoses → allergy rows (latest established entry per group)
  for (const [, g] of groups) {
    const est = g.dx.filter((x) => x.e.status === "active" || x.e.status === "resolved");
    if (!est.length) continue;
    const cur = est[est.length - 1];
    const dc = drugCaused(cur.e);
    if (!dc) continue;
    const label: string = cur.e.label;
    const low = label.toLowerCase();
    let substance: string | undefined;
    let rx: string | undefined;
    const drugs = cur.doc.entries.filter((x) => x[1].type === "home_med").map((x) => x[1]);
    const named = KNOWN_DRUGS.find((d) => low.includes(d)) ?? drugs.map((m) => ingredientName(m.drug_name)).find((n) => n && low.includes(n));
    let cls = CLASSES.find((c) => c.re.test(label));
    if (named) {
      substance = named;
      rx = drugs.find((m) => ingredientName(m.drug_name) === named)?.rxnorm_ingredient;
    } else if (cls) {
      const inClass = drugs.filter((m) => cls!.members.includes(ingredientName(m.drug_name) ?? ""));
      const ings = new Set(inClass.map((m) => ingredientName(m.drug_name)));
      if (ings.size === 1) { substance = [...ings][0]; rx = inClass[0].rxnorm_ingredient; }
      else substance = cls.name;
    } else {
      const m = low.match(/adverse (?:effect|reaction) of (.+?)(?:,|$| \()/);
      substance = m ? m[1].trim() : undefined;
    }
    if (!substance) continue;
    let rtype: AllergyIntoleranceRow["reaction_type"] = "serious_adverse_event";
    if (/angioedema|anaphyla|urticaria|hives|rash|bronchospasm|hypersens/.test(low)) rtype = "hypersensitivity";
    else if (/cough|nausea|myalgia|gi upset|diarrhea/.test(low)) rtype = "side_effect";
    const mech: AllergyIntoleranceRow["mechanism"] =
      rtype === "hypersensitivity" ? (cls?.nonImmune ? "non_immune" : "unknown")
      : rtype === "serious_adverse_event" && /ketoacidosis|\bdka\b|acidosis|hyperkal/.test(low) ? "non_immune" : "unknown";
    const row: AllergyIntoleranceRow = {
      substance, reaction_type: rtype, mechanism: mech, reaction: label,
      criticality: rtype === "side_effect" ? "low" : "high",
      evidence: [{ item_id: cur.doc.item.id, entry_id: cur.id }],
    };
    if (rx) row.rxnorm_ingredient = String(rx);
    const prev = seenAllergy.get(substance);
    if (prev) { prev.evidence.push(...row.evidence); continue; }
    seenAllergy.set(substance, row);
    dxAllergies.push(row);
  }
  return { problems, dxAllergies };
}

// ───────────── allergies ─────────────

function buildAllergies(docs: Doc[]): AllergyIntoleranceRow[] {
  const withList = docs.filter((d) => d.entries.some((e) => e[1].type === "allergy"));
  if (!withList.length) return [];
  const doc = withList[withList.length - 1];
  const rows: AllergyIntoleranceRow[] = [];
  for (const [id, e] of doc.entries) {
    if (e.type !== "allergy" || !e.substance) continue;
    const sub = String(e.substance).trim();
    if (/^(nkda|nka|no known (drug )?allergies)$/i.test(sub)) continue;
    const rs = String(e.reaction ?? "").toLowerCase();
    const lowSub = sub.toLowerCase();
    let rtype: AllergyIntoleranceRow["reaction_type"];
    if (/hives|urticaria|rash|angioedema|anaphyla|swelling|wheez|bronchospasm|itch|pruritus|throat|shortness of breath|dyspnea|hypersens|edema/.test(rs)) rtype = "hypersensitivity";
    else if (/ketoacidosis|lactic|hyperkal|liver|hepatotox|renal failure|bleed|rhabdo|pancreatitis|toxicity|acidosis|stevens|seizure/.test(rs)) rtype = "serious_adverse_event";
    else if (rs) rtype = "side_effect";
    else rtype = e.severity === "mild" ? "side_effect" : "hypersensitivity";
    const aceI = CLASSES[1].members.includes(lowSub) || CLASSES[1].re.test(lowSub);
    let mech: AllergyIntoleranceRow["mechanism"] = "unknown";
    if (aceI && /cough|angioedema/.test(rs)) mech = "non_immune";
    else if (rtype === "serious_adverse_event" && /ketoacidosis|acidosis/.test(rs)) mech = "non_immune";
    const row: AllergyIntoleranceRow = {
      substance: lowSub, reaction_type: rtype, mechanism: mech,
      criticality: e.severity === "mild" ? "low" : e.severity === "severe" ? "high" : "unknown",
      evidence: [{ item_id: doc.item.id, entry_id: id }],
    };
    if (e.rxnorm_ingredient) row.rxnorm_ingredient = String(e.rxnorm_ingredient);
    if (e.reaction) row.reaction = String(e.reaction);
    rows.push(row);
  }
  return rows;
}

// ───────────── labs ─────────────

